--
-- Name: location_for_stuff(); Type: FUNCTION; Schema: headers; Owner: -
--

CREATE FUNCTION headers.location_for_stuff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
    insert into headers_private.stuff values (new.id, new.name);
    if new.id is not null then
      perform set_config(
        'response.headers',
        format('[{"Location": "/%s?id=eq.%s&overriden=true"}]', tg_table_name, new.id),
        true
      );
    end if;
    return new;
end
$$;


